css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .field { position: absolute; inset: 0; border-radius: 50%; background: color-mix(in srgb, var(--accent) 18%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent); }
.loader .wet { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from -150deg, transparent 0deg, color-mix(in srgb, var(--accent) 30%, transparent) 30deg, color-mix(in srgb, var(--accent) 75%, transparent) 150deg, transparent 152deg); animation: pivot-turn calc(var(--loader-speed) * 4) linear infinite; }
.loader .arm { position: absolute; left: 50%; top: 50%; width: 46%; height: 6%; margin-top: -3%; transform-origin: 0 50%; background: linear-gradient(90deg, #cbd5e1, #64748b); border-radius: 3px; animation: pivot-turn calc(var(--loader-speed) * 4) linear infinite; }
.loader .arm i { position: absolute; top: 90%; width: 8%; height: 130%; border-radius: 50%; background: var(--accent-2); opacity: .8; animation: pivot-spray calc(var(--loader-speed) * .7) ease-in-out infinite; }
.loader .arm i:nth-of-type(1) { left: 26%; }
.loader .arm i:nth-of-type(2) { left: 54%; animation-delay: calc(var(--loader-speed) * .23); }
.loader .arm i:nth-of-type(3) { left: 82%; animation-delay: calc(var(--loader-speed) * .46); }
.loader .hub { position: absolute; left: 43%; top: 43%; width: 14%; height: 14%; border-radius: 50%; background: linear-gradient(#94a3b8, #334155); }
@keyframes pivot-turn { to { transform: rotate(1turn); } }
@keyframes pivot-spray { 0%, 100% { transform: scaleY(.7); opacity: .5; } 50% { transform: scaleY(1.25); opacity: .95; } }
